# C: pointers and memory (50 problems). Exercises about printing real memory addresses are rewritten as checks that give the same answer on every machine.
IN = [("int", "n")]
A = [("arr", "n a")]
M = [("mat", "r c a")]
S = [("str", "s")]
S2 = [("str", "s"), ("str", "t")]
LINE = [("line", "s")]
T = "Pointers"
cq("c-ptr-address-of", "Address-of and Value-at", "EASY", T, "Read an integer `x`, store the address of `x` in `int *p = &x;` and print `Value: <*p>` and `Same address: Yes` if `p == &x`. (The real address changes from run to run, so only the comparison is printed.)", "One integer.", "Two lines.",
   '    int *p = &x;\n    printf("Value: %d\\n", *p);\n    printf("Same address: %s\\n", p == &x ? "Yes" : "No");', ["10", "-5", "0", "999", "42"], [("int", "x")])
cq("c-ptr-dereference", "Change a Value Through a Pointer", "EASY", T, "Read `x`, make `int *p = &x;`, add 10 through the pointer (`*p += 10`) and print `x`.", "One integer.", "The new value of `x`.",
   '    int *p = &x;\n    *p += 10;\n    printf("%d\\n", x);', ["5", "-10", "0", "100", "7"], [("int", "x")])
cq("c-ptr-add", "Add with Pointers", "EASY", T, "Read `a` and `b`, keep them in pointers `pa` and `pb`, and print `*pa + *pb`.", "One line with two integers.", "The sum.",
   '    int *pa = &a, *pb = &b;\n    printf("%d\\n", *pa + *pb);', ["3 4", "-5 5", "0 0", "100 200", "7 -9"], [("int", "a b")])
cq("c-ptr-max", "Larger of Two with Pointers", "EASY", T, "Read two integers and print the larger one by comparing `*pa` and `*pb`.", "One line with two integers.", "The larger number.",
   '    int *pa = &a, *pb = &b;\n    printf("%d\\n", *pa > *pb ? *pa : *pb);', ["3 9", "9 3", "-4 -9", "5 5", "0 -1"], [("int", "a b")])
cq("c-ptr-swap-main", "Swap with Pointers", "EASY", T, "Read `a` and `b` and swap them using only the pointers `pa` and `pb` (a temporary int is allowed). Print `a b`.", "One line with two integers.", "The swapped values.",
   '    int *pa = &a, *pb = &b;\n    int t = *pa;\n    *pa = *pb;\n    *pb = t;\n    printf("%d %d\\n", a, b);', ["3 5", "-7 2", "0 0", "100 -100", "15 30"], [("int", "a b")])
cq("c-ptr-arithmetic", "Pointer Arithmetic", "MEDIUM", T, "Read an array of at least 3 integers. Set `int *p = a;` then print three values on one line: `*p`, then `*(p + 2)`, then after `p += 2; p--;` print `*p` again.", "First line `n` (at least 3), then `n` integers.", "Three numbers.", "3 <= n <= 1000",
   '    int *p = a;\n    int first = *p, third = *(p + 2);\n    p += 2;\n    p--;\n    printf("%d %d %d\\n", first, third, *p);', [arr([10, 20, 30]), arr([1, 2, 3, 4, 5]), arr([-1, 0, 1]), arr([7, 8, 9, 10]), arr([100, 200, 300, 400, 500, 600])], A)
cq("c-ptr-array-print", "Print an Array with Pointer Notation", "EASY", T, "Print the elements on one line using `*(a + i)` instead of `a[i]`.", "First line `n`, then `n` integers.", "The array.", "1 <= n <= 1000",
   '    for (int i = 0; i < n; i++) printf("%d%s", *(a + i), i < n - 1 ? " " : "");\n    printf("\\n");', [arr([1, 2, 3, 4, 5]), arr([7]), arr([10, -3, 8, 8]), arr([0, 0]), arr([-1, -2, -3])], A)
cq("c-ptr-array-sum", "Sum with a Pointer", "EASY", T, "Walk through the array with a pointer `p` (`p < a + n`) and print the sum.", "First line `n`, then `n` integers.", "The sum.", "1 <= n <= 1000",
   '    long long sum = 0;\n    for (int *p = a; p < a + n; p++) sum += *p;\n    printf("%lld\\n", sum);', [arr([1, 2, 3, 4]), arr([10]), arr([-5, 5, 10]), arr([100, 200, 300, 401]), arr([7, 7, 7])], A)
cq("c-ptr-max-min", "Largest and Smallest with Pointers", "EASY", T, "Use a pointer to walk the array. Print `Maximum: <x>` and `Minimum: <y>`.", "First line `n`, then `n` integers.", "Two lines.", "1 <= n <= 1000",
   '    int *mx = a, *mn = a;\n    for (int *p = a; p < a + n; p++) {\n        if (*p > *mx) mx = p;\n        if (*p < *mn) mn = p;\n    }\n    printf("Maximum: %d\\nMinimum: %d\\n", *mx, *mn);', [arr([3, 9, 1]), arr([5]), arr([-4, -9, -1]), arr([100, 50, 75, 200]), arr([2, 2, 2])], A)
cq("c-ptr-copy-array", "Copy an Array with Pointers", "EASY", T, "Copy the array into `b` using two pointers, then print `b`.", "First line `n`, then `n` integers.", "The copy.", "1 <= n <= 1000",
   '    int b[1000];\n    int *src = a, *dst = b;\n    while (src < a + n) *dst++ = *src++;\n    for (int i = 0; i < n; i++) printf("%d%s", b[i], i < n - 1 ? " " : "");\n    printf("\\n");', [arr([1, 2, 3]), arr([7]), arr([10, -3, 8]), arr([0, 0, 0, 0]), arr([-1, 5])], A)
cq("c-ptr-reverse-array", "Reverse an Array with Pointers", "MEDIUM", T, "Reverse the array in place with a pointer at each end that move towards each other. Print it.", "First line `n`, then `n` integers.", "The reversed array.", "1 <= n <= 1000",
   '    int *lo = a, *hi = a + n - 1;\n    while (lo < hi) {\n        int t = *lo;\n        *lo++ = *hi;\n        *hi-- = t;\n    }\n    for (int i = 0; i < n; i++) printf("%d%s", a[i], i < n - 1 ? " " : "");\n    printf("\\n");', [arr([1, 2, 3, 4, 5]), arr([7]), arr([10, -3, 8, 8]), arr([5, 4, 3, 2, 1, 0]), arr([-1, -2, -3, -4])], A)
cq("c-ptr-search-array", "Search with a Pointer", "EASY", T, "After the array read `key`. Walk a pointer through the array and print `Found at index <i>` (0-based, first match) or `Not found`.", "First line `n`, second line `n` integers, third line `key`.", "One line.", "1 <= n <= 1000",
   '    for (int *p = a; p < a + n; p++) {\n        if (*p == key) {\n            printf("Found at index %d\\n", (int)(p - a));\n            return 0;\n        }\n    }\n    printf("Not found\\n");', [arr([4, 8, 15, 16]) + "15\n", arr([4, 8, 15, 16]) + "99\n", arr([5, 5, 5]) + "5\n", arr([1]) + "1\n", arr([9, 8, 7]) + "7\n"], A + [("int", "key")])
cq("c-ptr-sort-array", "Sort with Pointers", "MEDIUM", T, "Sort the array ascending with bubble sort written using pointer notation (`*(a + j)`). Print it.", "First line `n`, then `n` integers.", "The sorted array.", "1 <= n <= 500",
   '    for (int i = 0; i < n - 1; i++)\n        for (int j = 0; j < n - 1 - i; j++)\n            if (*(a + j) > *(a + j + 1)) {\n                int t = *(a + j);\n                *(a + j) = *(a + j + 1);\n                *(a + j + 1) = t;\n            }\n    for (int i = 0; i < n; i++) printf("%d%s", *(a + i), i < n - 1 ? " " : "");\n    printf("\\n");', [arr([5, 2, 9, 1]), arr([7]), arr([3, 3, 1]), arr([5, 4, 3, 2, 1]), arr([-1, 5, -3, 2])], A)
cq("c-ptr-modify-in-function", "Modify an Array in a Function", "MEDIUM", T, "Write `void doubleAll(int *p, int n)` that doubles every element through the pointer. Call it and print the array.", "First line `n`, then `n` integers.", "The doubled array.", "1 <= n <= 1000",
   '    doubleAll(a, n);\n    for (int i = 0; i < n; i++) printf("%d%s", a[i], i < n - 1 ? " " : "");\n    printf("\\n");', [arr([1, 2, 3]), arr([7]), arr([-1, 0, 5]), arr([100, 200]), arr([4, 4, 4, 4])], A, defs="void doubleAll(int *p, int n) {\n    for (int i = 0; i < n; i++) *(p + i) *= 2;\n}")
cq("c-ptr-string-length", "String Length with a Pointer", "EASY", T, "Read a word. Move a pointer to the end-of-string marker and print the length as the distance travelled.", "One word (up to 100 characters).", "The length.", "1 <= length <= 100",
   '    char *p = s;\n    while (*p) p++;\n    printf("%d\\n", (int)(p - s));', ["hello", "a", "programming", "NextByte", "12345"], S)
cq("c-ptr-string-copy", "Copy a String with Pointers", "EASY", T, "Copy the word into another array using only pointers (no `strcpy`) and print the copy.", "One word (up to 100 characters).", "The copy.", "1 <= length <= 100",
   '    char t[101];\n    char *src = s, *dst = t;\n    while ((*dst++ = *src++) != \'\\0\');\n    printf("%s\\n", t);', ["hello", "a", "programming", "NextByte", "12345"], S)
cq("c-ptr-string-concat", "Join Two Strings with Pointers", "MEDIUM", T, "Read two words and join the second to the end of the first using pointers (no `strcat`). Print the result.", "One line with two words.", "The joined word.", "Each word at most 50 characters",
   '    char out[202];\n    char *d = out;\n    for (char *p = s; *p; p++) *d++ = *p;\n    for (char *p = t; *p; p++) *d++ = *p;\n    *d = \'\\0\';\n    printf("%s\\n", out);', ["hello world", "a b", "Next Byte", "abc 123", "x y"], S2)
cq("c-ptr-string-compare", "Compare Strings with Pointers", "MEDIUM", T, "Compare two words letter by letter with pointers. Print `Less` if the first comes before the second in dictionary order, `Greater` if after, `Equal` if the same.", "One line with two words.", "`Less`, `Greater` or `Equal`.", "Each word at most 100 characters",
   '    char *p = s, *q = t;\n    while (*p && *p == *q) { p++; q++; }\n    if (*p == *q) printf("Equal\\n");\n    else if (*p < *q) printf("Less\\n");\n    else printf("Greater\\n");', ["apple banana", "banana apple", "same same", "abc abcd", "abcd abc"], S2)
cq("c-ptr-string-reverse", "Reverse a String with Pointers", "MEDIUM", T, "Reverse the word in place with two pointers, one at each end. Print it.", "One word (up to 100 characters).", "The reversed word.", "1 <= length <= 100",
   '    char *lo = s, *hi = s;\n    while (*hi) hi++;\n    hi--;\n    while (lo < hi) {\n        char t = *lo;\n        *lo++ = *hi;\n        *hi-- = t;\n    }\n    printf("%s\\n", s);', ["hello", "a", "level", "NextByte", "12345"], S)
cq("c-ptr-count-vowels", "Vowels and Consonants with Pointers", "EASY", T, "Read a line of text. Using a pointer, count vowels (a e i o u, either case) and consonants (other letters). Print `Vowels: <x>` and `Consonants: <y>`.", "One line of text.", "Two lines.", "At most 255 characters",
   '    int v = 0, c = 0;\n    for (char *p = s; *p; p++) {\n        char ch = *p;\n        if (ch >= \'A\' && ch <= \'Z\') ch += 32;\n        if (ch == \'a\' || ch == \'e\' || ch == \'i\' || ch == \'o\' || ch == \'u\') v++;\n        else if (ch >= \'a\' && ch <= \'z\') c++;\n    }\n    printf("Vowels: %d\\nConsonants: %d\\n", v, c);', ["hello world", "AEIOU", "xyz", "Programming in C", "123 !!"], LINE)
cq("c-ptr-to-uppercase", "Uppercase with Pointers", "EASY", T, "Read a line of text and change every small letter to a capital using a pointer. Print it.", "One line of text.", "The text in capitals.", "At most 255 characters",
   '    for (char *p = s; *p; p++) if (*p >= \'a\' && *p <= \'z\') *p -= 32;\n    printf("%s\\n", s);', ["hello world", "ABC", "Next Byte 2026", "mixed Case", "123 !!"], LINE)
cq("c-ptr-to-lowercase", "Lowercase with Pointers", "EASY", T, "Read a line of text and change every capital letter to a small one using a pointer. Print it.", "One line of text.", "The text in small letters.", "At most 255 characters",
   '    for (char *p = s; *p; p++) if (*p >= \'A\' && *p <= \'Z\') *p += 32;\n    printf("%s\\n", s);', ["HELLO WORLD", "abc", "Next Byte 2026", "Mixed Case", "123 !!"], LINE)
cq("c-ptr-palindrome", "Palindrome with Pointers", "EASY", T, "Print `Yes` if the word reads the same backwards, else `No`, comparing from both ends with pointers.", "One word (up to 100 characters).", "`Yes` or `No`.", "1 <= length <= 100",
   '    char *lo = s, *hi = s;\n    while (*hi) hi++;\n    hi--;\n    int ok = 1;\n    while (lo < hi) if (*lo++ != *hi--) ok = 0;\n    printf("%s\\n", ok ? "Yes" : "No");', ["level", "hello", "a", "abba", "noon1"], S)
cq("c-ptr-substring-search", "Find a Substring", "MEDIUM", T, "Read a text word and a pattern word. Print the index (0-based) of the first place the pattern appears in the text, or `Not found`. Use pointers.", "One line: `text pattern`.", "The index or `Not found`.", "Each word at most 100 characters",
   '    for (char *p = s; *p; p++) {\n        char *a = p, *b = t;\n        while (*a && *b && *a == *b) { a++; b++; }\n        if (*b == \'\\0\') {\n            printf("%d\\n", (int)(p - s));\n            return 0;\n        }\n    }\n    printf("Not found\\n");', ["programming gram", "hello xyz", "aaaa aa", "abc abc", "abc abcd"], S2)
cq("c-ptr-tokenize", "Split a Sentence into Words", "MEDIUM", T, "Read one line of words separated by single or several spaces. Print each word on its own line, using pointers to find where each word starts and ends.", "One line of text.", "One word per line.", "At most 255 characters",
   '    char *p = s;\n    while (*p) {\n        while (*p == \' \') p++;\n        if (!*p) break;\n        char *start = p;\n        while (*p && *p != \' \') p++;\n        printf("%.*s\\n", (int)(p - start), start);\n    }', ["hello world", "one", "a  b   c", "Next Byte is fun", "  leading and trailing  "], LINE)

T = "Pointers and memory"
cq("c-ptr-row-sums", "Row Sums via Pointer to Array", "MEDIUM", T, "Write `int rowSum(int (*row)[50], int c)`... that is hard to read, so use `int rowSum(const int *row, int c)`: pass each row to it and print the sum of each row, one per line.", "First line `r c`, then the matrix.", "`r` lines.", "1 <= r, c <= 50",
   '    for (int i = 0; i < r; i++) printf("%d\\n", rowSum(a[i], c));', [mt([[1, 2, 3], [4, 5, 6]]), mt([[5]]), mt([[1, 1], [2, 2], [3, 3]]), mt([[0, 0], [0, 0]]), mt([[-1, 1, -1]])], M, defs="int rowSum(const int *row, int c) {\n    int s = 0;\n    for (int j = 0; j < c; j++) s += *(row + j);\n    return s;\n}")
cq("c-ptr-matrix-sum", "Matrix Sum with Pointers", "EASY", T, "Print the sum of all elements, reading them through a pointer `*(*(a + i) + j)`.", "First line `r c`, then the matrix.", "The sum.", "1 <= r, c <= 50",
   '    long long sum = 0;\n    for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) sum += *(*(a + i) + j);\n    printf("%lld\\n", sum);', [mt([[1, 2, 3], [4, 5, 6]]), mt([[5]]), mt([[-1, 1], [2, -2]]), mt([[10, 20, 30, 40]]), mt([[1], [2], [3]])], M)
cq("c-ptr-matrix-transpose", "Transpose with Pointers", "MEDIUM", T, "Print the transpose of the matrix, reading elements with pointer notation.", "First line `r c`, then the matrix.", "A `c x r` matrix.", "1 <= r, c <= 50",
   '    for (int j = 0; j < c; j++) {\n        for (int i = 0; i < r; i++) printf("%d%s", *(*(a + i) + j), i < r - 1 ? " " : "");\n        printf("\\n");\n    }', [mt([[1, 2, 3], [4, 5, 6]]), mt([[5]]), mt([[1, 2], [3, 4]]), mt([[1, 2, 3, 4]]), mt([[1], [2], [3]])], M)
cq("c-ptr-double-pointer", "Pointer to a Pointer", "EASY", T, "Read `x`. Make `int *p = &x;` and `int **pp = &p;`. Double `x` through `**pp` and print `x` and `**pp` on one line.", "One integer.", "`<x> <**pp>`.",
   '    int *p = &x;\n    int **pp = &p;\n    **pp *= 2;\n    printf("%d %d\\n", x, **pp);', ["5", "-3", "0", "100", "21"], [("int", "x")])
cq("c-ptr-malloc-single", "malloc a Single Integer", "EASY", T, "Allocate one `int` with `malloc`, store `x * 2` in it, print it, then `free` it.", "One integer.", "The doubled value.",
   '    int *p = malloc(sizeof(int));\n    *p = x * 2;\n    printf("%d\\n", *p);\n    free(p);', ["5", "-3", "0", "100", "21"], [("int", "x")], inc="#include <stdlib.h>\n")
cq("c-ptr-malloc-average", "Average of a malloc Array", "MEDIUM", T, "Read `n`, allocate an array of `n` ints with `malloc`, read the numbers and print their average with two decimals. Free the array.", "First line `n`, then `n` integers.", "The average.", "1 <= n <= 1000",
   '    int *a = malloc(n * sizeof(int));\n    long long sum = 0;\n    for (int i = 0; i < n; i++) {\n        scanf("%d", &a[i]);\n        sum += a[i];\n    }\n    printf("%.2f\\n", (double)sum / n);\n    free(a);', [arr([1, 2, 3, 4]), arr([10]), arr([-5, 5, 10]), arr([100, 200, 300, 401]), arr([7, 7, 7])], IN, inc="#include <stdlib.h>\n")
cq("c-ptr-calloc-zero", "calloc Starts at Zero", "MEDIUM", T, "Read `n` and allocate `n` ints with `calloc`. Print `Zeros: <count of elements equal to 0>`. Then set `p[i] = i * i` and print `Sum of squares: <sum>`.", "One integer.", "Two lines.", "1 <= n <= 1000",
   '    int *p = calloc(n, sizeof(int));\n    int zeros = 0;\n    for (int i = 0; i < n; i++) if (p[i] == 0) zeros++;\n    long long sum = 0;\n    for (int i = 0; i < n; i++) { p[i] = i * i; sum += p[i]; }\n    printf("Zeros: %d\\nSum of squares: %lld\\n", zeros, sum);\n    free(p);', ["5", "1", "10", "100", "1000"], IN, inc="#include <stdlib.h>\n")
cq("c-ptr-realloc-grow", "Grow an Array with realloc", "MEDIUM", T, "Read `n` and `n` integers into a `malloc` array. Then `realloc` it to hold `n + 3` ints, set the three new slots to 0, 1, 2 and print the whole array. If `realloc` returns `NULL` print `Allocation failed`.", "First line `n`, then `n` integers.", "The array of `n + 3` numbers.", "1 <= n <= 1000",
   '    int *a = malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) scanf("%d", &a[i]);\n    int *b = realloc(a, (n + 3) * sizeof(int));\n    if (b == NULL) {\n        printf("Allocation failed\\n");\n        return 1;\n    }\n    for (int i = 0; i < 3; i++) b[n + i] = i;\n    for (int i = 0; i < n + 3; i++) printf("%d%s", b[i], i < n + 2 ? " " : "");\n    printf("\\n");\n    free(b);', [arr([5, 6, 7]), arr([1]), arr([-1, -2]), arr([9, 8, 7, 6]), arr([0])], IN, inc="#include <stdlib.h>\n")
cq("c-ptr-dynamic-max", "Largest in a Dynamic Array", "EASY", T, "Allocate the array with `malloc`, read it and print the largest value using a pointer.", "First line `n`, then `n` integers.", "The largest.", "1 <= n <= 1000",
   '    int *a = malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) scanf("%d", &a[i]);\n    int *mx = a;\n    for (int *p = a; p < a + n; p++) if (*p > *mx) mx = p;\n    printf("%d\\n", *mx);\n    free(a);', [arr([3, 9, 1]), arr([5]), arr([-4, -9, -1]), arr([100, 50, 75, 200]), arr([2, 2, 2])], IN, inc="#include <stdlib.h>\n")
cq("c-ptr-struct-arrow", "Struct Pointer and the Arrow", "MEDIUM", T, "Read `n` students (`name marks`). Keep them in an array of `struct Student`; walk a pointer `p` over the array and print `<name>: <marks>` for each, using `p->name` and `p->marks`.", "First line `n`, then `n` lines `name marks`.", "`n` lines.", "1 <= n <= 100",
   '    struct Student s[100];\n    for (int i = 0; i < n; i++) scanf("%31s %d", s[i].name, &s[i].marks);\n    for (struct Student *p = s; p < s + n; p++) printf("%s: %d\\n", p->name, p->marks);', ["3\nasha 82\nravi 91\nmeena 77", "1\nkiran 50", "2\na 1\nb 2", "4\nw 10\nx 20\ny 30\nz 40", "2\nsana 100\nomar 99"], IN, defs="struct Student {\n    char name[32];\n    int marks;\n};")
cq("c-ptr-dynamic-structs", "Dynamic Array of Structs", "MEDIUM", T, "Read `n` students (`name marks`) into an array allocated with `malloc` and print the average marks with two decimals.", "First line `n`, then `n` lines `name marks`.", "The average.", "1 <= n <= 100",
   '    struct Student *s = malloc(n * sizeof(struct Student));\n    long long sum = 0;\n    for (int i = 0; i < n; i++) {\n        scanf("%31s %d", (s + i)->name, &(s + i)->marks);\n        sum += (s + i)->marks;\n    }\n    printf("%.2f\\n", (double)sum / n);\n    free(s);', ["3\nasha 82\nravi 91\nmeena 77", "1\nkiran 50", "2\na 1\nb 2", "4\nw 10\nx 20\ny 30\nz 40", "2\nsana 100\nomar 99"], IN, inc="#include <stdlib.h>\n", defs="struct Student {\n    char name[32];\n    int marks;\n};")
cq("c-ptr-self-referential", "A Self-Referential Node", "MEDIUM", T, "Read three integers. Make three `struct Node`s (`int data; struct Node *next;`), link them in the order read and print the chain as `a -> b -> c`.", "One line with three integers.", "The chain.", "|values| <= 1000",
   '    struct Node n1 = {a, NULL}, n2 = {b, NULL}, n3 = {c, NULL};\n    n1.next = &n2;\n    n2.next = &n3;\n    for (struct Node *p = &n1; p; p = p->next) printf("%d%s", p->data, p->next ? " -> " : "\\n");', ["1 2 3", "5 5 5", "-1 0 1", "100 200 300", "9 8 7"], [("int", "a b c")], defs="struct Node {\n    int data;\n    struct Node *next;\n};")
cq("c-ptr-function-pointer", "Call Through a Function Pointer", "MEDIUM", T, "Write `add`, `sub` and `mul` (each takes two ints). Read `a b op` where `op` is 0 for add, 1 for subtract, 2 for multiply. Store the three functions in an array of function pointers and print the result of the chosen one.", "One line: `a b op`.", "The result.", "|a|, |b| <= 1000, op in {0, 1, 2}",
   '    int (*ops[])(int, int) = {add, sub, mul};\n    printf("%d\\n", ops[op](a, b));', ["6 3 0", "6 3 1", "6 3 2", "-4 5 2", "100 200 1"], [("int", "a b op")], defs="int add(int a, int b) {\n    return a + b;\n}\n\nint sub(int a, int b) {\n    return a - b;\n}\n\nint mul(int a, int b) {\n    return a * b;\n}")
cq("c-ptr-callback-sort", "Sort with a Callback", "HARD", T, "Write `int ascending(int a, int b)` and `int descending(int a, int b)` (each returns true when `a` should come before `b`), and `void sortWith(int *a, int n, int (*before)(int, int))`, a bubble sort that uses the callback. Read a flag (0 ascending, 1 descending) then the array, and print the sorted array.", "First line the flag, then `n`, then `n` integers.", "The sorted array.", "1 <= n <= 500",
   '    sortWith(a, n, flag ? descending : ascending);\n    for (int i = 0; i < n; i++) printf("%d%s", a[i], i < n - 1 ? " " : "");\n    printf("\\n");', ["0\n" + arr([5, 2, 9, 1]), "1\n" + arr([5, 2, 9, 1]), "0\n" + arr([7]), "1\n" + arr([3, 3, 1]), "0\n" + arr([-1, 5, -3, 2])], [("int", "flag")] + A, defs="int ascending(int a, int b) {\n    return a < b;\n}\n\nint descending(int a, int b) {\n    return a > b;\n}\n\nvoid sortWith(int *a, int n, int (*before)(int, int)) {\n    for (int i = 0; i < n - 1; i++)\n        for (int j = 0; j < n - 1 - i; j++)\n            if (before(a[j + 1], a[j])) {\n                int t = a[j];\n                a[j] = a[j + 1];\n                a[j + 1] = t;\n            }\n}")
cq("c-ptr-generic-search", "Generic Search with void*", "HARD", T, "Write `int findIndex(const void *base, int n, size_t size, const void *key, int (*same)(const void *, const void *))` that returns the index of the first element equal to `key` (or -1) for any element type. Use it with ints: read the array and a key, print the index or `Not found`.", "First line `n`, second line `n` integers, third line `key`.", "The index or `Not found`.", "1 <= n <= 1000",
   '    int idx = findIndex(a, n, sizeof(int), &key, sameInt);\n    if (idx < 0) printf("Not found\\n");\n    else printf("%d\\n", idx);', [arr([4, 8, 15, 16]) + "15\n", arr([4, 8, 15, 16]) + "99\n", arr([5, 5, 5]) + "5\n", arr([1]) + "1\n", arr([9, 8, 7]) + "9\n"], A + [("int", "key")], inc="#include <stddef.h>\n", defs="int sameInt(const void *x, const void *y) {\n    return *(const int *)x == *(const int *)y;\n}\n\nint findIndex(const void *base, int n, size_t size, const void *key, int (*same)(const void *, const void *)) {\n    const char *p = base;\n    for (int i = 0; i < n; i++)\n        if (same(p + i * size, key)) return i;\n    return -1;\n}")
cq("c-ptr-char-bytes", "The Bytes of an Integer", "HARD", T, "Read a non-negative `unsigned int` and look at its memory with an `unsigned char *`. Print the four bytes in memory order as `Byte 0: <v>` ... `Byte 3: <v>` (on a little-endian computer byte 0 is the lowest one).", "One integer 0 to 4294967295.", "Four lines.", "0 <= x <= 4294967295",
   '    unsigned char *p = (unsigned char *)&x;\n    for (int i = 0; i < 4; i++) printf("Byte %d: %u\\n", i, p[i]);', ["1", "256", "16909060", "4294967295", "0"], [("unsigned int", "x")])
cq("c-ptr-2d-array-of-pointers", "Row Sums of a Dynamic Matrix", "MEDIUM", T, "Allocate a matrix as an array of row pointers (`int **m`) with `malloc`, read it, print each row's sum, one per line, and free everything.", "First line `r c`, then the matrix.", "`r` lines.", "1 <= r, c <= 50",
   '    int **m = malloc(r * sizeof(int *));\n    for (int i = 0; i < r; i++) {\n        m[i] = malloc(c * sizeof(int));\n        int s = 0;\n        for (int j = 0; j < c; j++) {\n            scanf("%d", &m[i][j]);\n            s += m[i][j];\n        }\n        printf("%d\\n", s);\n    }\n    for (int i = 0; i < r; i++) free(m[i]);\n    free(m);', [mt([[1, 2, 3], [4, 5, 6]]), mt([[5]]), mt([[1, 1], [2, 2], [3, 3]]), mt([[0, 0], [0, 0]]), mt([[-1, 1, -1]])], [("int", "r c")], inc="#include <stdlib.h>\n")
cq("c-ptr-contiguous-matrix", "Matrix in One Block", "MEDIUM", T, "Allocate the whole `r x c` matrix as one block `int *m = malloc(r * c * sizeof(int))` and reach element `(i, j)` as `m[i * c + j]`. Read it, then print the matrix with each row on a line.", "First line `r c`, then the matrix.", "The matrix.", "1 <= r, c <= 50",
   '    int *m = malloc(r * c * sizeof(int));\n    for (int i = 0; i < r * c; i++) scanf("%d", &m[i]);\n    for (int i = 0; i < r; i++) {\n        for (int j = 0; j < c; j++) printf("%d%s", m[i * c + j], j < c - 1 ? " " : "");\n        printf("\\n");\n    }\n    free(m);', [mt([[1, 2, 3], [4, 5, 6]]), mt([[5]]), mt([[1, 1], [2, 2], [3, 3]]), mt([[0, 0], [0, 0]]), mt([[-1, 1, -1]])], [("int", "r c")], inc="#include <stdlib.h>\n")
cq("c-ptr-free-matrix", "Free a 2D Matrix Properly", "MEDIUM", T, "Build an `r x c` matrix of row pointers where element `(i, j)` is `i * j`. Print the sum of all elements, free every row and then the pointer array, and finally print `Freed`.", "One line: `r c`.", "The sum, then `Freed`.", "1 <= r, c <= 50",
   '    int **m = malloc(r * sizeof(int *));\n    long long sum = 0;\n    for (int i = 0; i < r; i++) {\n        m[i] = malloc(c * sizeof(int));\n        for (int j = 0; j < c; j++) { m[i][j] = i * j; sum += m[i][j]; }\n    }\n    printf("%lld\\n", sum);\n    for (int i = 0; i < r; i++) free(m[i]);\n    free(m);\n    printf("Freed\\n");', ["3 4", "1 1", "5 5", "10 2", "50 50"], [("int", "r c")], inc="#include <stdlib.h>\n")
cq("c-ptr-null-after-free", "Set a Pointer to NULL After free", "EASY", T, "Allocate an `int`, store `x`, print it, `free` it and set the pointer to `NULL` so it cannot be used by mistake. Then print `Pointer is NULL: Yes` if `p == NULL`.", "One integer.", "Two lines.",
   '    int *p = malloc(sizeof(int));\n    *p = x;\n    printf("%d\\n", *p);\n    free(p);\n    p = NULL;\n    printf("Pointer is NULL: %s\\n", p == NULL ? "Yes" : "No");', ["5", "-3", "0", "100", "21"], [("int", "x")], inc="#include <stdlib.h>\n")
cq("c-ptr-leak-counter", "Count Allocations and Frees", "MEDIUM", T, "A memory leak happens when memory is allocated and never freed. Read `n`, allocate `n` blocks of 16 bytes (keep their pointers in an array), then free them all while counting. Print `Allocated: <n>`, `Freed: <count>` and `Leaked: <n - count>`.", "One integer.", "Three lines.", "1 <= n <= 1000",
   '    void *blocks[1000];\n    for (int i = 0; i < n; i++) blocks[i] = malloc(16);\n    int freed = 0;\n    for (int i = 0; i < n; i++) { free(blocks[i]); freed++; }\n    printf("Allocated: %d\\nFreed: %d\\nLeaked: %d\\n", n, freed, n - freed);', ["5", "1", "100", "1000", "7"], IN, inc="#include <stdlib.h>\n")
cq("c-ptr-read-lines", "Read Lines of Any Length", "HARD", T, "Read lines until the input ends. Each line may be long, so read it with a buffer that grows with `realloc`. For every line print `Line <k>: <length>` (k from 1, length without the newline).", "Any number of lines.", "One line per input line.", "At most 1000 lines of at most 5000 characters",
   '    int lineNo = 0;\n    int c;\n    size_t cap = 8, len = 0;\n    char *buf = malloc(cap);\n    while ((c = getchar()) != EOF) {\n        if (c == \'\\n\') {\n            printf("Line %d: %zu\\n", ++lineNo, len);\n            len = 0;\n            continue;\n        }\n        if (len + 1 >= cap) {\n            cap *= 2;\n            buf = realloc(buf, cap);\n        }\n        buf[len++] = c;\n    }\n    if (len > 0) printf("Line %d: %zu\\n", ++lineNo, len);\n    free(buf);', ["hello\nworld\n", "a\n", "a very long line indeed, longer than the starting buffer of eight\nshort\n", "one\n\nthree\n", "no newline at end"], (), inc="#include <stdlib.h>\n")
cq("c-ptr-linked-list-append", "Build a Linked List", "HARD", T, "Read `n` integers and add each to the **end** of a singly linked list (create each node with `malloc`). Print the list in order, separated by spaces, and free the nodes.", "First line `n`, then `n` integers.", "The list.", "1 <= n <= 1000",
   '    struct Node *head = NULL, *tail = NULL;\n    for (int i = 0; i < n; i++) {\n        struct Node *node = malloc(sizeof(struct Node));\n        scanf("%d", &node->data);\n        node->next = NULL;\n        if (tail) tail->next = node; else head = node;\n        tail = node;\n    }\n    for (struct Node *p = head; p; p = p->next) printf("%d%s", p->data, p->next ? " " : "\\n");\n    while (head) { struct Node *next = head->next; free(head); head = next; }', [arr([1, 2, 3]), arr([7]), arr([5, 4, 3, 2, 1]), arr([-1, 0, 1]), arr([9, 9])], IN, inc="#include <stdlib.h>\n", defs="struct Node {\n    int data;\n    struct Node *next;\n};")
cq("c-ptr-linked-list-double-pointer", "Insert at the Head with a Double Pointer", "HARD", T, "Write `void pushFront(struct Node **head, int value)` that adds a node at the front. Read `n` integers, push each in turn, and print the list from the head (so the last number read comes first).", "First line `n`, then `n` integers.", "The list.", "1 <= n <= 1000",
   '    struct Node *head = NULL;\n    for (int i = 0; i < n; i++) {\n        int v;\n        scanf("%d", &v);\n        pushFront(&head, v);\n    }\n    for (struct Node **pp = &head; *pp; pp = &(*pp)->next) printf("%d%s", (*pp)->data, (*pp)->next ? " " : "\\n");', [arr([1, 2, 3]), arr([7]), arr([5, 4, 3, 2, 1]), arr([-1, 0, 1]), arr([9, 9])], IN, inc="#include <stdlib.h>\n", defs="struct Node {\n    int data;\n    struct Node *next;\n};\n\nvoid pushFront(struct Node **head, int value) {\n    struct Node *node = malloc(sizeof(struct Node));\n    node->data = value;\n    node->next = *head;\n    *head = node;\n}")
cq("c-ptr-linked-list-reverse", "Reverse a Linked List", "HARD", T, "Build a list from `n` integers (in the order read) and reverse it **in place** by changing the `next` pointers (no new nodes). Print the reversed list.", "First line `n`, then `n` integers.", "The reversed list.", "1 <= n <= 1000",
   '    struct Node *head = NULL, *tail = NULL;\n    for (int i = 0; i < n; i++) {\n        struct Node *node = malloc(sizeof(struct Node));\n        scanf("%d", &node->data);\n        node->next = NULL;\n        if (tail) tail->next = node; else head = node;\n        tail = node;\n    }\n    struct Node *prev = NULL;\n    while (head) {\n        struct Node *next = head->next;\n        head->next = prev;\n        prev = head;\n        head = next;\n    }\n    for (struct Node *p = prev; p; p = p->next) printf("%d%s", p->data, p->next ? " " : "\\n");', [arr([1, 2, 3]), arr([7]), arr([5, 4, 3, 2, 1]), arr([-1, 0, 1]), arr([9, 8])], IN, inc="#include <stdlib.h>\n", defs="struct Node {\n    int data;\n    struct Node *next;\n};")
